import {validateMessage} from './validation.js';

describe('validateMessage: list_sessions', () => {
  it('accepts a bare list_sessions frame', () => {
    const result = validateMessage({type: 'list_sessions'});
    expect(result.valid).toBe(true);
  });

  it('accepts list_sessions with valid limit', () => {
    const result = validateMessage({type: 'list_sessions', limit: 10});
    expect(result.valid).toBe(true);
  });

  it('accepts list_sessions with valid before cursor', () => {
    const result = validateMessage({
      type: 'list_sessions',
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    });
    expect(result.valid).toBe(true);
  });

  it('rejects list_sessions with non-integer limit', () => {
    const result = validateMessage({type: 'list_sessions', limit: 'ten'});
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with negative limit', () => {
    const result = validateMessage({type: 'list_sessions', limit: -1});
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with fractional limit', () => {
    const result = validateMessage({type: 'list_sessions', limit: 1.5});
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with non-object before', () => {
    const result = validateMessage({type: 'list_sessions', before: 'not-an-object'});
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with empty sessionId in before', () => {
    const result = validateMessage({
      type: 'list_sessions',
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''},
    });
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with sessionId over 128 chars in before', () => {
    const result = validateMessage({
      type: 'list_sessions',
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
    });
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with invalid updatedAt in before', () => {
    const result = validateMessage({
      type: 'list_sessions',
      before: {updatedAt: 'not-a-date', sessionId: 's1'},
    });
    expect(result.valid).toBe(false);
  });

  it('rejects list_sessions with non-string updatedAt in before', () => {
    const result = validateMessage({
      type: 'list_sessions',
      before: {updatedAt: true, sessionId: 's1'},
    });
    expect(result.valid).toBe(false);
  });

  it('strips unknown fields like userId from list_sessions', () => {
    const result = validateMessage({type: 'list_sessions', userId: 'u2', limit: 10});
    if (!result.valid) throw new Error('Expected valid result');
    expect(result.data).toEqual({type: 'list_sessions'});
  });
});
EOF
